/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_slo_unchecked`.
#[inline]
pub fn size_prefixed_root_as_slo_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<SLO<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<SLO<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a SLO and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `SLO`.
#[inline]
pub unsafe fn root_as_slo_unchecked(buf: &[u8]) -> SLO<'_> {
    unsafe { ::flatbuffers::root_unchecked::<SLO>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed SLO and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `SLO`.
#[inline]
pub unsafe fn size_prefixed_root_as_slo_unchecked(buf: &[u8]) -> SLO<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<SLO>(buf) }
}

pub const SLO_IDENTIFIER: &str = "$SLO";

#[inline]
pub fn slo_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, SLO_IDENTIFIER, false)
}

#[inline]
pub fn slo_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, SLO_IDENTIFIER, true)
}

#[inline]
pub fn finish_slo_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<SLO<'a>>
) {
    fbb.finish(root, Some(SLO_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_slo_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<SLO<'a>>
) {
    fbb.finish_size_prefixed(root, Some(SLO_IDENTIFIER));
}
